import re
from shopkit.core.order_engine import parseOrderRef, formatOrderRef

def order_refs(text: str) -> list[str]:
    if not text:
        return []
    pattern = re.compile(r'\b(?:ord_[0-9a-f]{12}|SOB?[- ]?\d{4}[- ]?\d{1,6})\b', re.I)
    seen = set()
    result = []
    for m in pattern.finditer(text):
        parsed = parseOrderRef(m.group(0))
        if parsed:
            canonical = formatOrderRef(*parsed)
            if canonical not in seen:
                seen.add(canonical)
                result.append(canonical)
    return result

